"""Every member of a registry has a case of its own.

Covers ``MQC_CMN_UNI_112387``, inventoried in
``docs/design/cmn_verdict_and_cli.md`` section 10 and designed in
``harness_test_taxonomy.md`` section 1.1.

A failure here is **not a model finding**, so the module carries no priority marker.
"""

# ------------------------------------------------------------- cases in here
# Generated by `tools/refresh_case_summaries.py`.
#
# TestMQCCaseCoverage
#   112387  a_registry_member_without_a_case_of_its_own_is_reported
# ------------------------------------------------------------ end of cases

from pathlib import Path

import pytest

from cmn.case_coverage import uncovered_members

pytestmark = pytest.mark.unit

_MODULE = '''
class TestMQCSplit:
    def MQC_CMN_UNI_100001_alpha_case(self) -> None:
        self._check("alpha", 1)

    def MQC_CMN_UNI_100002_beta_case(self) -> None:
        self._check("beta", 2)

    def _check(self, member: str, value: int) -> None:
        self._other("gamma")

    def not_a_case(self) -> None:
        self._check("delta", 3)
'''


class TestMQCCaseCoverage:
    """A registry grows; its cases must grow with it."""

    def MQC_CMN_UNI_112387_a_registry_member_without_a_case_of_its_own_is_reported(
        self, tmp_path: Path
    ) -> None:
        """Members passed to the helper by an ``MQC_`` case are covered; others are not.

        A call from a helper or from a method that is not a case covers
        nothing.

        Design: ``harness_test_taxonomy.md`` section 1.1.

        Args:
            tmp_path (Path): Where the synthetic module is written.

        Returns:
            None
        """
        module = tmp_path / "mqc_uni_split.py"
        module.write_text(_MODULE, encoding="utf-8")

        assert not uncovered_members(module, "_check", ["alpha", "beta"])
        assert uncovered_members(module, "_check", ["alpha", "beta", "delta"]) == ["delta"]
        assert uncovered_members(module, "_check", ["gamma"]) == ["gamma"]
        assert uncovered_members(module, "_absent", ["alpha"]) == ["alpha"]
